(* [comment removed for export] *)
Definition bufreg (c : CC.cutpoint) (E' : env) (a : Z) : Prop :=
  match CC.cp_F c with [_; _; (pb, _, pn)] => uv E' pb <= a < uv E' pb + uv E' pn | _ => False end.
