(* [comment removed for export] *)
Lemma own_blocks : forall i E1 (M1 : mem) model1 pe ce sbe sce, HAMB i E1 M1 model1 -> nth i G.BLS [] = [(pe, ce); (sbe, sce)] ->
  block_range L (uv E1 pe) (uv E1 ce) /\ block_range L (uv E1 sbe) (uv E1 sce) /\ L5.defined M1 (uv E1 pe) (uv E1 ce) /\ L5.defined M1 (uv E1 sbe) (uv E1 sce) /\
