Lemma CEIL : hl_ceil L <= sp - 12800.
Proof. pose proof (PSIU.STKF I) as (_ & H & _). rewrite PSIU.SCRV in H. lia.
Qed.

(* [comment removed for export] *)
Lemma frame_low : forall i c E1 E' (M1 M' : mem) pe ce BLk, PSM2.foot_all i c 0%nat (SR.PS 0 [] [] []) (CC.TOther 0) = true -> nth i G.BLS [] = (pe, ce) :: BLk ->
