Definition newv (o : option Z) (old : Z) : Z := match o with None => old | Some z => z end.
Lemma leaf_state_g : forall i c k ps1 t pv lv pe ce d E1 E' R' (M1 M' Mx : mem) modelx bm bd stack buf,
  is_leaf i c k ps1 t -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) ->
  HAMB i E1 Mx modelx -> mem_grows Mx M' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  PSIU.contents I pv pe ce E1 M1 bm bd stack buf ->
  env_agree GT.NF E0 E' /\ know_ok RSEGS E' M' (PSM2.lcells ps1) /\ PSM2.vw i = Some (pv, pe, ce) /\
  uv E' (PB4.pv_level lv) = uv E1 (PB4.pv_level pv) /\ uv E' (PB4.pv_sb lv) = uv E1 (PB4.pv_sb pv) /\ uv E' (PB4.pv_send lv) = uv E1 (PB4.pv_send pv) /\ uv E' (PB4.pv_scend lv) = uv E1 (PB4.pv_scend pv) /\
