Lemma leaf_state : forall i c k ps1 t pv lv pe ce d E1 R1 E' R' (M1 M' : mem) model1 bm bd stack buf,
  is_leaf i c k ps1 t -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) ->
  CC.At (hl_segs L) c E1 R1 M1 -> HAMB i E1 M1 model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  PSIU.contents I pv pe ce E1 M1 bm bd stack buf ->
  env_agree GT.NF E0 E' /\ know_ok RSEGS E' M' (PSM2.lcells ps1) /\ PSM2.vw i = Some (pv, pe, ce) /\
  uv E' (PB4.pv_level lv) = uv E1 (PB4.pv_level pv) /\ uv E' (PB4.pv_sb lv) = uv E1 (PB4.pv_sb pv) /\ uv E' (PB4.pv_send lv) = uv E1 (PB4.pv_send pv) /\ uv E' (PB4.pv_scend lv) = uv E1 (PB4.pv_scend pv) /\
  uv E' (PB4.pv_wend lv) = wend /\ uv E' pe = uv E1 pe /\ uv E' ce = uv E1 ce /\
  (uv E' (PB4.pv_st pv) = uv E1 (PB4.pv_st pv) /\ uv E' (PB4.pv_more pv) = uv E1 (PB4.pv_more pv) /\ uv E' (PB4.pv_level pv) = uv E1 (PB4.pv_level pv)) /\
  uv E' (PB4.pv_st lv) = match PSM2.d_st d with None => uv E1 (PB4.pv_st pv) | Some e => uv E' e end /\
  uv E' (PB4.pv_sst lv) = newv (PSM2.d_sst d) (uv E1 (PB4.pv_sst pv)) /\ uv E' (PB4.pv_nst lv) = newv (PSM2.d_nst d) (uv E1 (PB4.pv_nst pv)) /\
  uv E' (PB4.pv_more lv) = newv (PSM2.d_more d) (uv E1 (PB4.pv_more pv)) /\ uv E' (PB4.pv_done lv) = newv (PSM2.d_done d) (uv E1 (PB4.pv_done pv)) /\
  uv E' (PB4.pv_size lv) = (if PSM2.d_clr d then 0 else uv E1 (PB4.pv_size pv)) /\
  uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d /\ 0 <= PSM2.d_adv d <= 1 /\ uv E' (PB4.pv_wptr lv) <= wend /\
  L5.bytes_at RSEGS M' (uv E1 (PB4.pv_sb pv)) stack /\
  (PSM2.foot2 c = true -> forall a, 0 <= a < sp - 12800 -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) /\
  (forall a, 0x10000 <= a < 0xfe000 -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) /\
  (forall bm' bd', uv E' (PB4.pv_more lv) = PML.b2z bm' -> uv E' (PB4.pv_done lv) = PML.b2z bd' ->
     exists bufm, PML.parser_at M' P (PSIU.ps_of lv pe ce E' bm' bd' stack bufm) /\ Z.of_nat (length bufm) = uv E' (PB4.pv_size lv) /\
                  (PSM2.d_clr d = false -> uv E1 (PB4.pv_st pv) = PML.ST_NUMBER -> PSM2.foot2 c = true -> bufm = buf)) /\
