(* [comment removed for export] *)
Lemma frame_vs2 : forall i c E1 E' (M1 M' Mx : mem) model1 pe ce BLk, PSM2.foot_all i c 0%nat (SR.PS 0 [] [] []) (CC.TOther 0) = true -> nth i G.BLS [] = (pe, ce) :: BLk -> HAMB i E1 Mx model1 ->
