(* [comment removed for export] *)
Hypothesis GOTO_SIM : forall i c k ps1 j s, is_leaf i c k ps1 (CC.TGoto j s) -> forall E1 R1 E' R' (M1 M' : mem) model1, CC.At (hl_segs L) c E1 R1 M1 ->
  HAMB i E1 M1 model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> XI i E1 M1 -> PSIU.SIM I eg i E1 M1 -> PSIU.SIM I eg j (CC.env_over GT.NF s E') M'.
(* [comment removed for export] *)
